// ===== Faction card pictures: illustrations for MHA, AoT, Solo Leveling, One Punch Man, Hunter x Hunter =====
const FACIMG={"mha": "data:image/jpeg;base64,", "aot": "data:image/jpeg;base64,", "sl": "data:image/jpeg;base64,", "opm": "data:image/jpeg;base64,", "hxh": "data:image/jpeg;base64,", "sds": "data:image/jpeg;base64,", "dbz": "data:image/jpeg;base64,"};

const FACIMGI={};for(const f in FACIMG){const im=new Image();im.onload=()=>{try{drawPortraits();}catch(_){}};im.src=FACIMG[f];FACIMGI[f]=im;}
{const _dp=drawPortraits;drawPortraits=function(){_dp();for(const f in FACIMGI){const im=FACIMGI[f],cv=document.getElementById('p'+f);if(!cv||!im.complete||!im.naturalWidth)continue;const c=cv.getContext('2d'),W=cv.width,H=cv.height;
  c.save();c.clearRect(0,0,W,H);c.beginPath();c.roundRect(0,0,W,H,W*.12);c.clip();c.drawImage(im,0,0,W,H);c.restore();}};}
